@'
import json, urllib.request, urllib.error
auth=json.load(open(r"C:\Users\win\.codex\auth.json",encoding="utf-8"))
key=auth["OPENAI_API_KEY"]

def get(url):
    req=urllib.request.Request(url, headers={"Authorization": f"Bearer {key}"})
    with urllib.request.urlopen(req, timeout=20) as r:
        return json.load(r)

def post(url, data):
    body=json.dumps(data).encode()
    req=urllib.request.Request(url, data=body, headers={"Authorization": f"Bearer {key}", "Content-Type":"application/json"}, method="POST")
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            return r.status, r.read(250).decode("utf-8","replace")
    except urllib.error.HTTPError as e:
        return e.code, e.read(350).decode("utf-8","replace")

models=get("https://api.tangguo.xin/v1/models")
ids=[m.get("id") for m in models.get("data",[])]
print("model_count", len(ids))
for i in ids:
    print(" -", i)

candidates=[i for i in ids if any(x in i.lower() for x in ["gpt-5","o3","codex","5.4","5.5","5.6","sol","terra"])]
print("candidates", candidates[:40])
for m in (candidates[:8] or ids[:5]):
    code, body = post("https://api.tangguo.xin/v1/responses", {"model": m, "input":"ping", "store": False})
    print(f"responses[{m}] -> {code} {body[:180].replace(chr(10),' ')}")
